 function setEnabled(value){bells.forEach(b=>b.disabled=!value)}
 function flash(note, duration=360){const b=bells[note];b.classList.add('lit');tone(note);const float=$('noteFloat');float.textContent=['♪','♫','♬'][note];float.classList.remove('show');void float.offsetWidth;float.classList.add('show');setTimeout(()=>{b.classList.remove('lit');float.classList.remove('show')},duration)}
 function buildDots(){const wrap=$('dots');wrap.innerHTML='';patterns[round].forEach((_,i)=>{const d=document.createElement('span');d.className='dot'+(i<inputIndex?' done':'');d.id='dot'+i;wrap.appendChild(d)})}
 function update(){ $('roundTitle').textContent=completed?'All songs complete!':`Song ${round+1}`;$('roundPill').textContent=completed?'KITTY IS HOME!':(ready?'YOUR TURN!':'LISTEN UP!');$('levelCount').textContent=completed?'3 / 3':`${round+1} / 3`;$('starCount').textContent=`${stars} ⭐`;$('progress').style.width=`${completed?100:(round*100/3)}%`;$('progressLabel').textContent=completed?'All songs sung!':`${patterns[round].length} notes to go`;buildDots() }
-function startSong(){if(playing||completed)return;playing=true;ready=false;inputIndex=0;setEnabled(false);update();$('startBtn').textContent='♪ Listening…';$('listenText').textContent='Listen closely…';setFeedback('Here comes the little bell song!');buildDots();patterns[round].forEach((note,i)=>setTimeout(()=>{flash(note,420);const dot=$('dot'+i);if(dot)dot.classList.add('active');setTimeout(()=>dot&&dot.classList.remove('active'),410)},650+i*730));setTimeout(()=>{playing=false;ready=true;inputIndex=0;setEnabled(true);$('startBtn').textContent='↻ Hear it again';$('listenText').textContent='Your turn! Repeat the song.';$('roundPill').textContent='YOUR TURN!';setFeedback('Tap the bells in the same order!');buildDots()},650+patterns[round].length*730)}
+function startSong(){if(playing||completed)return;if(soundOn)audio();playing=true;ready=false;inputIndex=0;setEnabled(false);update();$('startBtn').textContent='♪ Listening…';$('listenText').textContent='Listen closely…';setFeedback('Here comes the little bell song!');buildDots();patterns[round].forEach((note,i)=>setTimeout(()=>{flash(note,420);const dot=$('dot'+i);if(dot)dot.classList.add('active');setTimeout(()=>dot&&dot.classList.remove('active'),410)},650+i*730));setTimeout(()=>{playing=false;ready=true;inputIndex=0;setEnabled(true);$('startBtn').textContent='↻ Hear it again';$('listenText').textContent='Your turn! Repeat the song.';$('roundPill').textContent='YOUR TURN!';setFeedback('Tap the bells in the same order!');buildDots()},650+patterns[round].length*730)}
 function nextSong(){if(round<2){round++;inputIndex=0;ready=false;playing=false;update();$('listenText').textContent='A new song is ready!';$('startBtn').textContent='▶ Hear the song';$('roundPill').textContent='LISTEN UP!';$('instruction').textContent='This song has one more note. Listen carefully, then play it back!';setFeedback('Lovely! Kitty is a little higher!','good');$('kitty').style.top=`${14-round*18}px`; $('bucket').style.top=`${76-round*8}px`;setEnabled(false)}else{completed=true;ready=false;update();$('kitty').classList.add('raised');$('listenText').textContent='Meow! What a lovely song!';$('roundPill').textContent='KITTY IS HOME!';$('startBtn').textContent='Play again';$('instruction').textContent='You did it! Kitty is safe and singing with all her garden friends.';setFeedback('Three songs, three stars — hooray!','good');setEnabled(false);setTimeout(()=>showModal('🎉','Hooray, Kitty!','You played all three songs beautifully. Kitty is out of the well and singing with her friends! You earned '+stars+' stars.','Sing again!'),650)}}
 function handle(note){if(!ready||playing||completed)return;flash(note,250);const correct=patterns[round][inputIndex]===note;if(!correct){setFeedback('Oops! Listen once more and try again.','try');inputIndex=0;buildDots();$('listenText').textContent='Let’s try that song again.';return}const dot=$('dot'+inputIndex);if(dot)dot.classList.add('done');inputIndex++;if(inputIndex===patterns[round].length){ready=false;stars++;update();setFeedback(['Perfect! Ding dong!','Beautiful bell playing!','Meow-sical!'][round],'good');$('listenText').textContent='You got every note!';setEnabled(false);sparkles();nextSong()}else{setFeedback(`${inputIndex} of ${patterns[round].length} notes — keep going!`,'good')}}
 function sparkles(){for(let i=0;i<9;i++){const s=document.createElement('span');s.className='sparkle';s.textContent=['✨','⭐','🌸'][i%3];s.style.left=(38+Math.random()*25)+'vw';s.style.top=(35+Math.random()*25)+'vh';s.style.setProperty('--x',(Math.random()*150-75)+'px');document.body.appendChild(s);setTimeout(()=>s.remove(),900)}}
 function restart(){round=0;inputIndex=0;playing=false;ready=false;stars=0;completed=false;$('kitty').classList.remove('raised');$('kitty').style.top='14px';$('bucket').style.top='76px';$('instruction').textContent='Listen to the bell pattern. Then tap the bells in the same order!';$('listenText').textContent='Ready when you are!';$('startBtn').textContent='▶ Hear the song';setFeedback('Tap “Hear the song” to begin.');setEnabled(false);update()}
